:root {
  --ink-0: #07090c;
  --ink-1: #0d1117;
  --ink-2: #151b23;
  --line: #2a3441;
  --line-strong: #46566a;
  --text: #e8edf2;
  --muted: #9ba8b8;
  --cost: #ffbf47;
  --queued: #8793a1;
  --running: #43b9ff;
  --done: #57d38c;
  --failed: #ff6470;
